import { test, expect } from "./helpers/portable-evidence";
import { enterChat, openBobDm, revealComposerTools } from "./helpers/session";

for (const attachment of [
  { kind: "file", path: "/tmp/large.bin", button: "composer-attach" },
  { kind: "image", path: "/tmp/photo.png", button: "composer-image" },
])
  test(`${attachment.kind} sender keeps confirmed upload percent and ETA visible until recipient custody`, async ({
    page,
  }, testInfo) => {
    await enterChat(page);
    await openBobDm(page);
    await page.evaluate((path) => {
      const win = window as unknown as Window & {
        __upload: {
          id: string;
          done: number;
          delivered: boolean;
          consent: "pending" | "accepted";
        };
        __TAURI_INTERNALS__: {
          invoke: (
            cmd: string,
            args: Record<string, unknown>,
          ) => Promise<unknown>;
        };
      };
      const original = win.__TAURI_INTERNALS__.invoke;
      win.__upload = {
        id: "",
        done: 0,
        delivered: false,
        consent: path.endsWith(".bin") ? "pending" : "accepted",
      };
      win.__TAURI_INTERNALS__.invoke = async (cmd, args) => {
        if (cmd === "plugin:dialog|open") return path;
        const result = await original(cmd, args);
        if (cmd === "owner_enqueue_file")
          win.__upload.id = (result as { id: string }).id;
        if (cmd === "owner_delivery_statuses")
          return (result as Array<{ id: string; status: string }>).map((row) =>
            row.id === win.__upload.id
              ? {
                  ...row,
                  // The offer arrives before approval or file bytes. Its
                  // receipt must not retire the file's progress refresh.
                  status: "delivered",
                  file_progress: {
                    done: win.__upload.done,
                    total: 8,
                    delivered: win.__upload.delivered,
                    consent: win.__upload.consent,
                  },
                }
              : row,
          );
        return result;
      };
    }, attachment.path);
    await revealComposerTools(page);
    await page.getByTestId(attachment.button).click();
    const bubble = page.getByTestId("message-bubble").last();
    await expect(
      bubble.locator('[data-delivery="delivered"]'),
    ).toHaveAccessibleName("File offer received");
    if (attachment.kind === "file") {
      await expect(
        bubble.getByText("Waiting for recipient approval…", { exact: true }),
      ).toBeVisible();
      await page.evaluate(() => {
        (
          window as unknown as { __upload: { consent: string } }
        ).__upload.consent = "accepted";
      });
    }
    await expect(
      bubble.getByRole("progressbar", {
        name: /Waiting for file transfer to start/,
      }),
    ).toHaveAttribute("aria-valuenow", "0");
    await page.evaluate(
      () =>
        ((window as unknown as { __upload: { done: number } }).__upload.done =
          2),
    );
import { defineConfig, devices } from "@playwright/test";
import { createHash } from "node:crypto";

const worktreePort =
  5200 +
  (parseInt(createHash("sha256").update(process.cwd()).digest("hex").slice(0, 4), 16) %
    1000);
const port = Number(
  process.env.MESH_TALK_E2E_PORT ?? (process.env.CI ? 5173 : worktreePort),
);
// Keep browser navigation and server binding on the same address family.
const url = `http://127.0.0.1:${port}`;

// Browser E2E for the Mesh-Talk UI. Runs the Vite dev server + drives the real React app in
// headless Chromium with a mocked Tauri IPC layer (see e2e/tauri-mock.ts).
export default defineConfig({
  testDir: "./e2e",
  // Cold Windows transforms and browser coverage instrumentation can consume
  // the 30s default before a multi-step scenario completes.
  timeout:
    process.platform === "win32" || process.env.MESH_TALK_E2E_COVERAGE === "1"
      ? 90_000
      : 30_000,
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 1 : 0,
  // A single macOS worker avoids Vite asset decode retries and page-load
  // timeouts seen in the full suite with four concurrent browsers. CI already
  // uses one; Windows keeps its existing four-worker limit.
  workers:
    process.env.CI || process.platform === "darwin"
      ? 1
      : process.platform === "win32"
        ? 4
        : undefined,
  reporter: process.env.CI ? "list" : "html",
  snapshotPathTemplate: "e2e/{testFileName}-snapshots/{arg}{ext}",
  expect: {
    toHaveScreenshot: {
      maxDiffPixelRatio: 0.015,
    },
  },
  use: {
    baseURL: url,
    timezoneId: "Asia/Tokyo",
    trace: "retain-on-failure",
  },
  projects: [{ name: "chromium", use: { ...devices["Desktop Chrome"] } }],
  webServer: {
    command: `npm run dev -- --host 127.0.0.1 --port ${port}`,
    env: { MESH_TALK_E2E: "1" },
    url,
    // Another worktree may already have Vite on this port. Reusing it can
    // silently test an older checkout and report a false pass or failure.
    reuseExistingServer: false,
    timeout: 120_000,
  },
});
