import { expect } from "../tauri-mock";
import type { Theme } from "@/lib/theme";
import { seedMarketPacks } from "./packs";

export const BOB = { account: "acc_bob_bbbb2222", device: "device_bob_2222" };
export const CAROL = {
  account: "acc_carol_cccc3333",
  device: "device_carol_3333",
};
export const CHANNEL = { id: "chan_team_dddd4444" };

export async function waitForChatShell(page: Page) {
  // Lazy chat loading includes cold transforms and coverage instrumentation.
  // Keep startup's platform budget separate from behavior assertions.
  await expect(page.getByTestId("chat-shell")).toBeVisible({
    timeout:
      process.platform === "win32" || process.env.MESH_TALK_E2E_COVERAGE === "1"
        ? 90_000
        : 15_000,
  });
}

export async function enterChatShell(page: Page, user = "tester", path = "/") {
  await page.goto(path);
  await page.getByTestId("login-tab-signin").click();
  await page.getByTestId("login-username").fill(user);
  await page.getByTestId("login-password").fill("password123");
  await page.getByTestId("login-submit").click();
  await waitForChatShell(page);
}

export async function enterChat(page: Page, user = "tester", path = "/") {
  await enterChatShell(page, user, path);
  await expect(
    page.getByTestId(`conversation-row-${BOB.account}`),
  ).toBeVisible();
}

export async function seedTheme(page: Page, theme: Theme) {
  await page.addInitScript(
    (nextTheme) => localStorage.setItem("mesh-talk-theme", nextTheme),
    theme,
  );
}

export async function openBobDm(page: Page) {
  await page.getByTestId(`conversation-row-${BOB.account}`).click();
  await expect(page.getByTestId("conversation-header")).toBeVisible();
  await expect(page.getByText("hey, welcome to the mesh")).toBeVisible();
}

export async function revealComposerTools(page: Page) {
  const trigger = page.getByTestId("composer-more-tools");
  if ((await trigger.getAttribute("aria-expanded")) !== "true") {
    await trigger.click();
  }
}

export async function seedThemeBeforeLoad(page: Page, theme: string) {
  if (!["light", "dark", "oled"].includes(theme))
    await seedMarketPacks(page, [theme]);
  await page.addInitScript((nextTheme) => {
    localStorage.setItem("mesh-talk-theme", nextTheme);
  }, theme);
}
"}

